package studio.solocamera;
import org.json.*;
public final class EditorTracksTest {
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    public static void main(String[] args)throws Exception{
        EditorProject p=new EditorProject();EditorProject.Clip a=new EditorProject.Clip("video:a","A",10000),b=new EditorProject.Clip("video:b","B",10000);p.clips.add(a);p.clips.add(b);EditorProject.Caption text=new EditorProject.Caption();text.style=a.copy();text.style.text="Caption";text.at=0;text.end=10000;p.captions.add(text);
        EditorProject.Overlay o=new EditorProject.Overlay();o.clip=new EditorProject.Clip("video:o","Overlay",10000);o.at=1000;p.overlays.add(o);p.music="audio:m";p.musicDuration=5000;
        String beforeA=a.json().toString(),beforeB=b.json().toString();
        EditorEdits.trim(p,"Overlay",0,0,5000,1);check(o.clip.end==4000,"overlay source trim");check(a.json().toString().equals(beforeA)&&b.json().toString().equals(beforeB),"overlay trim changed main tracks");check(p.musicEnd==Long.MAX_VALUE,"overlay trim changed music");
        String beforeOverlay=o.json().toString();EditorEdits.trim(p,"Text",0,-1,2000,0);EditorEdits.trim(p,"Text",0,-1,4000,1);check(text.at==2000&&text.end==4000&&a.start==0&&a.end==10000,"text trim changed video");check(beforeOverlay.equals(o.json().toString()),"text trim changed overlay");
        String beforeVideo=a.json().toString();EditorEdits.trim(p,"Audio",0,-1,3000,0);EditorEdits.trim(p,"Audio",0,-1,9000,1);check(p.musicAt==3000&&p.musicEnd==9000,"audio bounds");check(a.json().toString().equals(beforeVideo)&&o.json().toString().equals(beforeOverlay),"audio trim changed video tracks");
        EditorEdits.trim(p,"Video",0,-1,6000,1);check(a.end==6000&&b.end==10000&&o.clip.end==4000&&p.musicEnd==9000&&text.at==2000&&text.end==4000,"main trim leaked to other tracks");
        o.at=18000;check(p.duration()==22000,"overlay end truncated by shorter main track");
        a.curveMaster=new double[]{.04,.18,.42,.82,.96};a.curveRed=new double[]{0,.2,.48,.7,1};a.curveStrength=.8;a.stretchX=1.7;a.stretchY=.6;a.zoom=2;a.cropX=.15;a.mask=2;a.feather=.3;a.animation=3;a.pitch=.65;EditorProject restored=EditorProject.from(p.json().toString());check(restored.clips.get(0).stretchX==1.7&&restored.clips.get(0).stretchY==.6&&restored.clips.get(0).mask==2&&restored.clips.get(0).zoom==2&&restored.clips.get(0).pitch==.65&&restored.clips.get(0).curveStrength==.8&&restored.clips.get(0).curveMaster[0]==.04&&restored.clips.get(0).curveRed[3]==.7&&restored.overlays.get(0).at==18000&&restored.musicAt==3000,"roundtrip lost track edits");
        JSONObject legacy=new JSONObject().put("uri","video:legacy").put("name","Legacy").put("duration",1000);EditorProject.Clip clean=EditorProject.Clip.from(legacy);check(clean.brightness==0&&clean.contrast==0&&clean.saturation==0&&clean.zoom==1&&clean.textEnd==Long.MAX_VALUE,"missing fields altered default look");
        EditorProject moves=new EditorProject();EditorProject.Clip first=new EditorProject.Clip("a","First",2000),second=new EditorProject.Clip("b","Second",2000);moves.clips.add(first);moves.clips.add(second);
        int moved=EditorEdits.moveVideo(moves,0,-1,-1,5000);check(moved==1&&moves.offset(0)==2000&&moves.offset(1)==5000&&moves.videoDuration()==7000,"main timestamp move lost gap or moved another clip");
        EditorProject loaded=EditorProject.from(moves.json().toString());check(loaded.offset(0)==2000&&loaded.offset(1)==5000,"timestamps lost on reload");
        moved=EditorEdits.moveVideo(moves,1,-1,0,700);check(moves.clips.size()==1&&moves.overlays.get(0).clip==first&&moves.overlays.get(0).at==700&&moves.offset(0)==2000,"main-to-overlay move lost clip or timestamp");
        moved=EditorEdits.moveVideo(moves,-1,0,-1,0);check(moved==0&&moves.overlays.isEmpty()&&moves.offset(0)==0&&moves.offset(1)==2000,"overlay-to-main failed");
        long collision=EditorEdits.availableMainTime(moves,0,1500,2000);check(collision==4000,"overlapping main drop was not placed in free space");
        EditorProject many=new EditorProject();many.clips.add(first.copy());for(int i=0;i<8;i++){EditorProject.Overlay layer=new EditorProject.Overlay();layer.clip=first.copy();layer.track=i;many.overlays.add(layer);EditorProject.Caption caption=new EditorProject.Caption();caption.style=first.copy();caption.track=i;caption.end=2000;many.captions.add(caption);}check(many.videoTracks()==8&&many.textTracks()==8,"Dynamic track count");EditorEdits.moveVideo(many,-1,7,0,0);check(many.overlays.get(1).track==0&&many.overlays.get(1).at==2000,"Same-row collision placement");
        EditorProject.Clip animated=first.copy();animated.font="serif";animated.bold=true;animated.shadowBlur=5;EditorMotion.Key k=EditorMotion.put(animated,0,false);k.x=-1;EditorMotion.Key end=EditorMotion.put(animated,1000,false);end.x=1;end.scale=2;check(Math.abs(EditorMotion.sample(animated,500,false).x)<.0001,"Linear interpolation midpoint");check(EditorMotion.sample(animated,2000,false).x==1,"Keyframe endpoint hold");k.x1=.42;k.y1=0;k.x2=1;k.y2=1;check(EditorMotion.sample(animated,500,false).x<0,"Ease-in curve ignored");EditorProject.Clip copy=EditorProject.Clip.from(animated.json());check(copy.bold&&copy.font.equals("serif")&&copy.shadowBlur==5&&copy.keys.size()==2&&copy.keys.get(0).x1==.42,"Keyframe and text style persistence");check(EditorProject.from(many.json().toString()).textTracks()==8,"Multiple text tracks lost on save");
        EditorProject.Clip styled=new EditorProject.Clip("x","Text",2000);check(!styled.backgroundEnabled&&!styled.shadowEnabled,"New text must default to transparent");styled.backgroundEnabled=true;styled.shadowEnabled=true;styled.backgroundPadding=24;styled.imageUri="image.png";EditorProject.Clip styledCopy=EditorProject.Clip.from(styled.json());check(styledCopy.backgroundEnabled&&styledCopy.shadowEnabled&&styledCopy.backgroundPadding==24&&styledCopy.imageUri.equals("image.png"),"Text toggles/image lost in draft");styled.fadeIn=500;styled.transitionIn=2;check(EditorMotion.white(styled,0)==1&&EditorMotion.white(styled,500)==0,"White transition endpoints");styled.transitionIn=4;check(EditorMotion.sample(styled,0,false).x==2&&EditorMotion.sample(styled,500,false).x==0,"Slide transition endpoints");
        for(int id=1;id<=20;id++){EditorProject.Clip tr=new EditorProject.Clip("t","Transition",2000);tr.transitionIn=tr.transitionOut=id;tr.fadeIn=tr.fadeOut=400;EditorProject.Clip saved=EditorProject.Clip.from(tr.json());check(saved.transitionIn==id&&saved.transitionOut==id,"Transition ID lost: "+id);for(boolean incoming:new boolean[]{true,false})for(int step=0;step<=100;step++){EditorTransitions.State state=EditorTransitions.phase(id,step/100.0,incoming);check(Double.isFinite(state.x+state.y+state.scale+state.rotation+state.gain+state.open)&&state.scale>0&&state.sx>0&&state.sy>0&&state.gain>=0&&state.gain<=1,"Invalid transition sample: "+id);}EditorTransitions.State neutral=EditorTransitions.sample(tr,1000);check(neutral.gain==1&&neutral.scale==1&&neutral.x==0&&neutral.y==0&&neutral.mask==0,"Transition leaked outside junction: "+id);EditorTransitions.State edge=EditorTransitions.phase(id,0,true);check(edge.gain==1&&edge.scale==1&&edge.rotation==0&&edge.open==1,"Transition endpoint discontinuity: "+id);}
        EditorProject.Clip tiny=new EditorProject.Clip("t","Tiny",1000);tiny.end=1;tiny.fadeIn=tiny.fadeOut=1000;tiny.transitionIn=16;check(Double.isFinite(EditorTransitions.sample(tiny,0).open),"Short-clip transition division");
        System.out.println("PASS all 20 transition IDs, endpoint continuity, bounded frame sampling, neutral holds and short clips");
        System.out.println("PASS text toggles, image draft persistence and transition endpoints");
        System.out.println("PASS dynamic tracks, same-row placement, keyframe interpolation, curves and styled text persistence");
        System.out.println("PASS timestamp moves, gaps, cross-track transfers, collision placement and saved timing");
        System.out.println("PASS independent video, overlay, caption and audio trim; project tail preservation; old/new draft round trip");
    }
}
